}

/// One new task attempt (`DeviceNewTaskModel`).
class NewTaskView {
  final int id;

  /// Bumped by every change of this view.
  final int revision;
  final bool ready;
  final bool sending;
  final String? error;
  final bool canRetry;

  /// A Cowork project: its chat is created on the first send.
  final bool flat;
  final CreatedWorktreeView? created;

  /// The worktree the creation got from the desktop, once it answered.
  final String? attemptWorktreeId;

  /// "Creating worktree…" until the desktop answered, then "Setting up
  /// worktree…".
  final String statusLabel;

  /// The chat the first message goes to.
  final ChatRefView? target;

  /// The first message was confirmed.
  final bool confirmed;

  const NewTaskView({
    required this.id,
    required this.revision,
    required this.ready,
    required this.sending,
    this.error,
    required this.canRetry,
    required this.flat,
    this.created,
    this.attemptWorktreeId,
    required this.statusLabel,
    this.target,
    required this.confirmed,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      revision.hashCode ^
      ready.hashCode ^
      sending.hashCode ^
      error.hashCode ^
      canRetry.hashCode ^
      flat.hashCode ^
      created.hashCode ^
      attemptWorktreeId.hashCode ^
      statusLabel.hashCode ^
      target.hashCode ^
      confirmed.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is NewTaskView &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          revision == other.revision &&
          ready == other.ready &&
          sending == other.sending &&
          error == other.error &&
          canRetry == other.canRetry &&
          flat == other.flat &&
          created == other.created &&
          attemptWorktreeId == other.attemptWorktreeId &&
          statusLabel == other.statusLabel &&
          target == other.target &&
          confirmed == other.confirmed;
}

